import { mock } from 'bun:test';
import assert from 'node:assert/strict';
import { JSDOM } from 'jsdom';
import { mergeCustomization } from '../../src/lib/customization';
const dom = new JSDOM('<div id="app"></div>', { url: 'https://tatakai.test/?customize=1' });
dom.window.matchMedia = (() => ({ matches: false, addEventListener() {}, removeEventListener() {} })) as any;
Object.assign(globalThis, { window: dom.window, document: dom.window.document, HTMLElement: dom.window.HTMLElement, Element: dom.window.Element, Node: dom.window.Node, MutationObserver: dom.window.MutationObserver, getComputedStyle: dom.window.getComputedStyle, IS_REACT_ACT_ENVIRONMENT: true, requestAnimationFrame: (callback: any) => setTimeout(callback, 0), cancelAnimationFrame: clearTimeout });
for (const key of ['HTMLFormElement', 'HTMLSelectElement', 'HTMLInputElement', 'HTMLButtonElement', 'HTMLOptionElement', 'SVGElement', 'Event', 'MouseEvent', 'CustomEvent', 'DocumentFragment']) (globalThis as any)[key] = (dom.window as any)[key];
let settings: any = { version: 1, themes: { dark: { targets: { desktop: { spotlight: { variant: 'classic', height: 500 }, pages: { 'anime-home': { sections: { spotlight: { spotlight: { variant: 'cinematic', height: 900 } } } } } } } } } };
let saved: any;
mock.module('../../src/hooks/ui/useCustomization', () => ({ useCustomization: () => ({ settings, userId: null, syncStatus: 'saved', savePatch: async (patch: any) => { saved = patch; settings = mergeCustomization(settings, patch); } }), useCustomizationScope: () => ({ themeId: 'dark', target: 'desktop' }) }));
mock.module('../../src/hooks/ui/useUiTranslation', () => ({ useUiTranslation: () => {} }));
mock.module('../../src/lib/customizationLabels', () => ({ customizationLabel: (value: string) => value, customizationMessage: (_: string, value: string, fields: any = {}) => value.replace(/\{\{(\w+)\}\}/g, (match, field) => fields[field] ?? match) }));
mock.module('../../src/components/settings/BackgroundEditor', () => ({ AppearanceBackground: () => null, BackgroundEditor: () => null, AppearanceDraftProvider: ({ children }: any) => children }));
mock.module('../../src/components/customization/CustomShelf', () => ({ SavedCustomShelf: () => null }));
mock.module('../../src/components/customization/CustomShelfEditor', () => ({ CustomShelfEditor: () => null }));
const { default: React, act } = await import('react');
const { createRoot } = await import('react-dom/client');
const { Simulate } = await import('react-dom/test-utils');
const { MemoryRouter } = await import('react-router-dom');
const { HomeCustomization } = await import('../../src/components/customization/HomeCustomization');
const { SpotlightPresentation, SpotlightPart, useSpotlightPresentation } = await import('../../src/components/customization/SpotlightPresentation');
let navigationCalls = 0;
function HeroProbe() {
  const presentation = useSpotlightPresentation();
  return <SpotlightPresentation><section data-spotlight-stage><span data-current-variant>{presentation?.variant || 'default'}</span><SpotlightPart part="title"><h1>Source title</h1></SpotlightPart><SpotlightPart part="details"><p>Source details</p></SpotlightPart><SpotlightPart part="description"><p>Source synopsis</p></SpotlightPart><SpotlightPart part="actions"><button onClick={() => navigationCalls++}>Source action</button></SpotlightPart><button id="imperative-navigation" onClick={() => navigationCalls++}>Imperative navigation</button></section></SpotlightPresentation>;
}
const root = createRoot(document.getElementById('app')!);
await act(async () => root.render(<MemoryRouter initialEntries={['/?customize=1']} future={{ v7_startTransition: true, v7_relativeSplatPath: true }}><HomeCustomization pageId="anime-home" sections={[{ id: 'spotlight', label: 'Spotlight', node: <HeroProbe /> }]} /></MemoryRouter>));
assert(!document.querySelector('[data-live-spotlight-preview="true"]'));
const settingsButton = document.querySelector<HTMLButtonElement>('button[aria-label="Settings for Spotlight"]')!;
await act(async () => settingsButton.click());
assert(document.querySelector('[data-live-spotlight-preview="true"]'));
assert(!document.querySelector('[data-live-spotlight-preview="true"] .home-edit-content'));
assert.equal(document.querySelector('[data-current-variant]')!.textContent, 'classic');
assert.equal(document.querySelector<HTMLElement>('[data-custom-spotlight]')!.style.getPropertyValue('--spotlight-height'), '500px');
const styleSelect = [...document.querySelectorAll('select')].find(select => [...select.options].some(option => option.value === 'cinematic'))!;
await act(async () => Simulate.change(styleSelect, { target: { value: 'cinematic' } } as any));
assert.equal(document.querySelector('[data-current-variant]')!.textContent, 'cinematic');
assert.equal(document.querySelectorAll('.spotlight-part-handle').length, 4);
const advanced = [...document.querySelectorAll('details')].find(details => details.querySelector('summary')?.textContent === 'Advanced')!;
advanced.open = true;
const heightInput = [...advanced.querySelectorAll('input')].find(input => input.closest('label')?.textContent?.startsWith('Height'))!;
await act(async () => Simulate.change(heightInput, { target: { value: '700' } } as any));
assert.equal(document.querySelector<HTMLElement>('[data-custom-spotlight]')!.style.getPropertyValue('--spotlight-height'), '700px');
const titlePosition = [...advanced.querySelectorAll('select')].find(select => select.closest('label')?.textContent?.startsWith('title'))!;
await act(async () => Simulate.change(titlePosition, { target: { value: 'top-left' } } as any));
assert(document.querySelector('[data-spotlight-stage] > [data-spotlight-part="title"][data-spotlight-placement="top-left"]'));
await act(async () => document.getElementById('imperative-navigation')!.click());
assert.equal(navigationCalls, 0);
const save = [...document.querySelectorAll('button')].find(button => button.textContent === 'Save')!;
await act(async () => save.click());
assert.equal(saved.themes.dark.targets.desktop.spotlight.variant, 'cinematic');
assert.equal(saved.themes.dark.targets.desktop.spotlight.placements.title, 'top-left');
assert.equal(saved.themes.dark.targets.desktop.pages, undefined);
assert.equal(document.querySelectorAll('.spotlight-part-handle').length, 0);
assert(document.querySelector('[data-spotlight-stage] > [data-spotlight-part="title"][data-spotlight-placement="top-left"]'));
await act(async () => document.getElementById('imperative-navigation')!.click());
assert.equal(navigationCalls, 1);
await act(async () => root.unmount());
dom.window.close();
console.log('live spotlight checks passed');
